// Rig documents pin (src/rig_config_pin.cpp): the ledger port against pancakebatter's own
// rig_events.py results (tools/fixtures/rig_config/ledgers/*.expected.json, generated by
// generate_expected.py), and every status of the start-snapshot block.
#include "rig_config_pin.h"

#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <set>
#include <sstream>
#include <string>

#include <unistd.h>

namespace fs = std::filesystem;
using json = nlohmann::json;
using namespace orange::recording;

namespace {

int failures = 0;

void require(bool ok, const std::string& what)
{
    if (!ok) {
        ++failures;
        std::cerr << "FAIL: " << what << "\n";
    }
}

std::string read_text(const fs::path& path)
{
    std::ifstream in(path, std::ios::binary);
    std::ostringstream buffer;
    buffer << in.rdbuf();
    return buffer.str();
}

void write_text(const fs::path& path, const std::string& text)
{
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out << text;
}

void test_ledgers_match_rig_events(const fs::path& fixtures)
{
    int count = 0;
    for (const auto& entry : fs::directory_iterator(fixtures / "ledgers")) {
        const std::string name = entry.path().filename().string();
        const std::string suffix = ".events.yml";
        if (name.size() <= suffix.size() || name.compare(name.size() - suffix.size(), suffix.size(), suffix) != 0) {
            continue;
        }
        const std::string stem = name.substr(0, name.size() - suffix.size());
        const json events = RigYamlToJson(read_text(entry.path())).at("events");
        const json expected = json::parse(read_text(fixtures / "ledgers" / (stem + ".expected.json")));
        const json active = RigEventsActiveConditions(events);
        const json attestations = RigEventsAttestations(events);
        require(active == expected.at("active_conditions"),
                stem + ": active conditions differ from rig_events.py\n  got      " + active.dump() +
                    "\n  expected " + expected.at("active_conditions").dump());
        require(attestations == expected.at("attestations"),
                stem + ": attestations differ from rig_events.py\n  got      " + attestations.dump() +
                    "\n  expected " + expected.at("attestations").dump());
        ++count;
    }
    require(count >= 5, "all ledger fixtures were compared");
}

void test_yaml_scalars()
{
    const json doc = RigYamlToJson(
        "a: 11\nb: '11'\nc: 1.5\nd: true\ne: ~\nf: ~/SpecSail/x.json\ng: \"2026-10-27\"\nh: >-\n  folded\n  text\n"
        "i: [x, 2]\nj: yes\nk: abc123\n");
    require(doc.at("a") == 11, "plain int");
    require(doc.at("b") == "11", "quoted int stays a string");
    require(doc.at("c") == 1.5, "plain float");
    require(doc.at("d") == true, "plain bool");
    require(doc.at("e").is_null(), "tilde is null");
    require(doc.at("f") == "~/SpecSail/x.json", "a path starting with ~ is a string");
    require(doc.at("g") == "2026-10-27", "quoted date stays a string");
    require(doc.at("h") == "folded text", "folded block scalar");
    require(doc.at("i") == json::array({"x", 2}), "flow sequence");
    require(doc.at("j") == true, "YAML 1.1 yes is true, as in PyYAML");
    require(doc.at("k") == "abc123", "plain text");
}

fs::path copy_installed(const fs::path& fixtures, const fs::path& tmp)
{
    fs::remove_all(tmp);
    fs::create_directories(tmp);
    for (const char* name : {"omnifin0.yml", "omnifin0.events.yml", "omnifin0.yml.source"}) {
        fs::copy_file(fixtures / "installed" / name, tmp / name);
    }
    return tmp;
}

void test_statuses(const fs::path& fixtures)
{
    const fs::path tmp = fs::temp_directory_path() / ("rig_config_pin_tests_" + std::to_string(::getpid()));
    const std::string t = "2026-10-28T03:00:00Z";
    std::set<std::string> seen;
    auto check_closed = [&seen](const json& pin) {
        const std::string status = pin.at("status").get<std::string>();
        bool known = false;
        for (const char* allowed : kRigConfigStatuses) known = known || status == allowed;
        require(known, "status " + status + " is in the closed list");
        require(pin.at("schema_id") == kRigConfigPinSchemaId && pin.at("schema_version") == kRigConfigPinSchemaVersion, "schema identity");
        seen.insert(status);
    };

    // Installed, sidecar agrees.
    fs::path dir = copy_installed(fixtures, tmp);
    json pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "pinned", "installed rig pins: " + pin.dump());
    require(pin.at("resolution").at("source") == "installed", "resolved from the installed directory");
    require(pin.at("resolution").at("recording_rig_id") == "omnifin0", "recording rig id named");
    require(pin.at("rig_id") == "omnifin0" && pin.at("rig_geometry_revision") == 10, "rig identity read");
    require(pin.at("source_sidecar").at("commit") == "7ba822c4cec21ed8540d22a367dc6b2afade4a2f", "commit pinned");
    require(pin.at("source_sidecar").at("rig_sha256_matches") == true, "rig sha agrees with the sidecar");
    require(pin.at("source_sidecar").at("events_sha256_matches") == true, "events sha agrees with the sidecar");
    require(pin.at("events_file").at("sha256") ==
                "fc949ac247840a1eb0d9e49e99ceedde4f1090508d5cafedbf70d571dc2f7018", "events sha256");
    require(pin.at("active_conditions").size() == 1 &&
                pin.at("active_conditions")[0].at("condition_id") == "c1" &&
                pin.at("active_conditions")[0].at("arenas") == json::array({"arena_2", "arena_3"}),
            "c1 sealed in full");
    require(pin.at("active_conditions")[0].at("locations").is_string(), "condition kept in full (locations)");
    require(pin.at("attestations").size() == 1 && pin.at("attestations")[0].at("event_id") == "e3" &&
                pin.at("attestations")[0].at("current_per_pancakebatter").is_null(),
            "e3 sealed; a sidecar without pancakebatter's verdict leaves current_per_pancakebatter null");
    require(pin.at("source_sidecar").at("current_attestations").is_null() &&
                pin.at("source_sidecar").at("orientation_sha256").is_null(),
            "no verdict lines in the sidecar");
    require(pin.at("warnings").empty(), "no warnings when pinned");

    // pancakebatter's verdict in the sidecar is copied, never recomputed.
    const std::string sidecar = read_text(dir / "omnifin0.yml.source");
    const std::string digest = pin.at("attestations")[0].at("orientation_sha256").get<std::string>();
    write_text(dir / "omnifin0.yml.source",
               sidecar + "orientation_sha256: " + digest + "\ncurrent_attestations.room_orientation: e3\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "pinned" && pin.at("attestations")[0].at("current_per_pancakebatter") == true,
            "e3 listed by pancakebatter is current: " + pin.dump());
    require(pin.at("source_sidecar").at("current_attestations") == json({{"room_orientation", {"e3"}}}) &&
                pin.at("source_sidecar").at("orientation_sha256") == digest,
            "verdict lines copied into source_sidecar");
    write_text(dir / "omnifin0.yml.source", sidecar + "current_attestations.room_orientation: e1, e3 ,e9\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    require(pin.at("source_sidecar").at("current_attestations").at("room_orientation") == json::array({"e1", "e3", "e9"}) &&
                pin.at("attestations")[0].at("current_per_pancakebatter") == true,
            "comma list with spaces");
    write_text(dir / "omnifin0.yml.source", sidecar + "current_attestations.room_orientation:\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    require(pin.at("source_sidecar").at("current_attestations").at("room_orientation") == json::array() &&
                pin.at("attestations")[0].at("current_per_pancakebatter") == false,
            "an empty verdict means no attestation is current");
    write_text(dir / "omnifin0.yml.source", sidecar + "current_attestations.other_field: e3\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    require(pin.at("attestations")[0].at("current_per_pancakebatter").is_null(),
            "no verdict line for the event's own field: unknown, not false");
    // A verdict not bound to the pinned bytes is not copied.
    write_text(dir / "omnifin0.yml.source", sidecar + "current_attestations.room_orientation: e3\n");
    write_text(dir / "omnifin0.events.yml", read_text(dir / "omnifin0.events.yml") + "\n# edited\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    require(pin.at("status") == "sidecar_mismatch" &&
                pin.at("attestations")[0].at("current_per_pancakebatter").is_null(),
            "verdict ignored when the ledger changed after install");
    dir = copy_installed(fixtures, tmp);
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);

    // Environment override wins and is named.
    pin = BuildRigConfigPin("", (dir / "omnifin0.yml").string(), "/nonexistent", t);
    check_closed(pin);
    require(pin.at("status") == "pinned" && pin.at("resolution").at("source") == "environment",
            "environment override pins and says so");
    require(pin.at("resolution").at("recording_rig_id").is_null(), "no recording rig id");

    // No rig id, no override.
    pin = BuildRigConfigPin("", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "rig_id_unknown", "unknown rig id");

    // Not installed: never a default.
    pin = BuildRigConfigPin("otherrig", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "not_installed" && pin.at("rig_file").is_null(), "missing rig file");

    // Rig file names another rig.
    pin = BuildRigConfigPin("omnifin1", (dir / "omnifin0.yml").string(), dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "rig_id_mismatch", "rig id mismatch");

    // Events ledger missing.
    fs::remove(dir / "omnifin0.events.yml");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "events_missing" && pin.at("events_file").at("status") == "missing",
            "events missing");
    require(pin.at("rig_file").at("sha256").is_string(), "the rig file is still pinned");

    // Installed copy changed after install.
    dir = copy_installed(fixtures, tmp);
    write_text(dir / "omnifin0.events.yml", read_text(dir / "omnifin0.events.yml") + "\n# edited\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "sidecar_mismatch" &&
                pin.at("source_sidecar").at("events_sha256_matches") == false,
            "sidecar mismatch");

    // Invalid YAML.
    dir = copy_installed(fixtures, tmp);
    write_text(dir / "omnifin0.yml", "rig_id: [unclosed\n");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "invalid", "invalid rig YAML");

    // Unreadable (a directory where the file should be).
    dir = copy_installed(fixtures, tmp);
    fs::remove(dir / "omnifin0.yml");
    fs::create_directory(dir / "omnifin0.yml");
    pin = BuildRigConfigPin("omnifin0", "", dir.string(), t);
    check_closed(pin);
    require(pin.at("status") == "unreadable" || pin.at("status") == "invalid", "unreadable rig file");

    fs::remove_all(tmp);
    require(seen.size() >= 7, "most statuses exercised");
}

void test_rig_id_from_geometry()
{
    require(RecordingRigIdFromGeometryContract({{"selection", {{"rig_id", "omnifin0"}}}}) == "omnifin0",
            "rig id from the geometry contract selection");
    require(RecordingRigIdFromGeometryContract(json::object()).empty(), "no selection, no rig id");
}

}  // namespace

int main(int argc, char** argv)
{
    if (argc < 2 || argc > 3) {
        std::cerr << "usage: rig_config_pin_tests <tools/fixtures/rig_config> [<rig_id>: print this host's pin]\n";
        return 2;
    }
    const fs::path fixtures = argv[1];
    if (argc == 3) {
        std::cout << BuildRigConfigPinForRecording(argv[2], "2026-10-28T00:00:00Z").dump(2) << "\n";
        return 0;
    }
    test_yaml_scalars();
    test_ledgers_match_rig_events(fixtures);
    test_statuses(fixtures);
    test_rig_id_from_geometry();
    if (failures != 0) {
        std::cerr << "rig_config_pin_tests: " << failures << " failure(s)\n";
        return 1;
    }
    std::cout << "rig_config_pin_tests: PASS\n";
    return 0;
}
